**b) Add two new mutation resolver methods** after `DeleteStoryboard`:

```go
// PublishStoryboard marks the storyboard as published (read-only).
// Requires MAINTAINER role, enforced by the @auth directive in the schema.
func (r *StoryboardResolver) PublishStoryboard(
    ctx context.Context,
    input graphmodel.PublishStoryboardInput,
) (*graphmodel.PublishStoryboardPayload, error) {
    const op = "StoryboardResolver.PublishStoryboard"

    if err := r.rl.Take(ctx, "mutation:publishStoryboard"); err != nil {
        return nil, apperr.ToGraphQLError(ctx, err)
    }

    sb, err := r.svc.PublishStoryboard(ctx, input.ID)
    if err != nil {
        r.logger.Error(op+" failed",
            zap.String("id", input.ID),
            zap.Error(err),
        )
        return nil, r.decorateError(ctx, err)
    }

    return &graphmodel.PublishStoryboardPayload{
        ClientMutationID: input.ClientMutationID,
        Storyboard:       graphmodel.FromDomainStoryboard(sb),
    }, nil
}

// UnpublishStoryboard removes the published status, restoring mutability.
// Requires MAINTAINER role, enforced by the @auth directive in the schema.
func (r *StoryboardResolver) UnpublishStoryboard(
    ctx context.Context,
    input graphmodel.UnpublishStoryboardInput,
) (*graphmodel.UnpublishStoryboardPayload, error) {
    const op = "StoryboardResolver.UnpublishStoryboard"

    if err := r.rl.Take(ctx, "mutation:unpublishStoryboard"); err != nil {
        return nil, apperr.ToGraphQLError(ctx, err)
    }

    sb, err := r.svc.UnpublishStoryboard(ctx, input.ID)
    if err != nil {
        r.logger.Error(op+" failed",
            zap.String("id", input.ID),
            zap.Error(err),
        )
        return nil, r.decorateError(ctx, err)
    }

    return &graphmodel.UnpublishStoryboardPayload{
        ClientMutationID: input.ClientMutationID,
        Storyboard:       graphmodel.FromDomainStoryboard(sb),
    }, nil
}
```

