       created_at, updated_at, deleted_at, published_at
FROM storyboards
WHERE tenant_id = $1
```

**d) Update the `Update` method's SQL** to also write `published_at` when it changes (add `published_at = :published_at` to the `SET` clause and add `"published_at": sb.PublishedAt` to the `params` map).

**e) Implement the two new methods** on `pgStoryboardRepo`:

```go
func (r *pgStoryboardRepo) Publish(ctx context.Context, tenantID, storyboardID uuid.UUID) error {
    const q = `
        UPDATE storyboards
        SET published_at = $1,
            updated_at   = $1,
            version      = version + 1
        WHERE tenant_id  = $2
          AND id         = $3
          AND deleted_at IS NULL
          AND published_at IS NULL
    `
    res, err := r.db.ExecContext(ctx, q, time.Now().UTC(), tenantID, storyboardID)
    if err != nil {
        return fmt.Errorf("publish storyboard: %w", err)
    }
    rows, _ := res.RowsAffected()
    if rows == 0 {
        return ErrNotFound // already published or not found; caller disambiguates
    }
    return nil
}

func (r *pgStoryboardRepo) Unpublish(ctx context.Context, tenantID, storyboardID uuid.UUID) error {
    const q = `
        UPDATE storyboards
        SET published_at = NULL,
            updated_at   = $1,
            version      = version + 1
        WHERE tenant_id  = $2
          AND id         = $3
          AND deleted_at IS NULL
          AND published_at IS NOT NULL
    `
    res, err := r.db.ExecContext(ctx, q, time.Now().UTC(), tenantID, storyboardID)
    if err != nil {
        return fmt.Errorf("unpublish storyboard: %w", err)
    }
    rows, _ := res.RowsAffected()
    if rows == 0 {
        return ErrNotFound
    }
    return nil
}
```

**f) Update `marshalStoryboardSnapshot`** to include `PublishedAt` in the snapshot struct so revision history captures the published state:

```go
