> ```

---

### 3. `internal/core/service/storyboard_service.go`

This file owns the `StoryboardService` interface and its implementation.

**a) Add a new sentinel error** near the top (after `ErrRateLimitExceeded`):

```go
// ErrStoryboardPublished is returned when a mutating operation is attempted
// on a published (read-only) storyboard.
var ErrStoryboardPublished = errors.New("storyboard is published")
```

**b) Add two new methods to the `StoryboardService` interface** (after `DeleteStoryboard`):

```go
PublishStoryboard(ctx context.Context, tenantID string, storyboardID uuid.UUID) (*domain.Storyboard, error)
UnpublishStoryboard(ctx context.Context, tenantID string, storyboardID uuid.UUID) (*domain.Storyboard, error)
```

**c) Implement both methods** on `storyboardServiceImpl` (after `DeleteStoryboard`):

```go
func (s *storyboardServiceImpl) PublishStoryboard(
    ctx context.Context,
    tenantID string,
    storyboardID uuid.UUID,
) (*domain.Storyboard, error) {
    if !s.consumeBudget() {
        return nil, ErrRateLimitExceeded
    }

    // Load the aggregate to enforce domain invariants (e.g. not deleted).
    sb, err := s.storyboardRepo.FindByID(ctx, tenantID, storyboardID, 0)
    if err != nil {
        if errors.Is(err, repository.ErrNotFound) {
            return nil, ErrStoryboardNotFound
        }
        return nil, fmt.Errorf("read storyboard for publish: %w", err)
    }

    // Delegate invariant enforcement to the aggregate root.
    if err := sb.Publish(); err != nil {
        return nil, err // ErrStoryboardDeleted or already published (nil)
    }

    start := time.Now()
    if err = s.storyboardRepo.Update(ctx, sb, sb.Version-1); err != nil {
        return nil, fmt.Errorf("persist publish: %w", err)
    }
    s.metric.Timing("storyboard.publish.ok", time.Since(start))
    s.logger.WithFields(logrus.Fields{
        "id":       storyboardID,
        "tenantID": tenantID,
    }).Info("storyboard published")

    _ = s.bus.Publish(ctx, eventbus.Event{
        Topic: "storyboard.published",
        Key:   sb.ID.String(),
        Data:  sb,
    })

    return sb, nil
}

func (s *storyboardServiceImpl) UnpublishStoryboard(
    ctx context.Context,
    tenantID string,
    storyboardID uuid.UUID,
) (*domain.Storyboard, error) {
    if !s.consumeBudget() {
        return nil, ErrRateLimitExceeded
    }

    sb, err := s.storyboardRepo.FindByID(ctx, tenantID, storyboardID, 0)
    if err != nil {
        if errors.Is(err, repository.ErrNotFound) {
            return nil, ErrStoryboardNotFound
        }
        return nil, fmt.Errorf("read storyboard for unpublish: %w", err)
    }

    if err := sb.Unpublish(); err != nil {
        return nil, err
    }

    start := time.Now()
    if err = s.storyboardRepo.Update(ctx, sb, sb.Version-1); err != nil {
        return nil, fmt.Errorf("persist unpublish: %w", err)
    }
    s.metric.Timing("storyboard.unpublish.ok", time.Since(start))
    s.logger.WithFields(logrus.Fields{
        "id":       storyboardID,
        "tenantID": tenantID,
    }).Info("storyboard unpublished")

    _ = s.bus.Publish(ctx, eventbus.Event{
        Topic: "storyboard.unpublished",
        Key:   sb.ID.String(),
        Data:  sb,
    })

    return sb, nil
}
```

**d) Update `UpdateStoryboard`** to guard against editing a published storyboard. After loading `sb` from the repo and before applying field changes, add:

```go
if sb.PublishedAt != nil {
    return nil, domain.ErrStoryboardPublished
}
```

